#!/usr/bin/env python3
"""PHYS1 analysis (planned/PHYS1_PREREG.md)."""
import json, glob
rd = lambda p: [json.loads(l) for f in glob.glob(p) for l in open(f) if l.strip()]
NEW = rd('out/phys1/*.jsonl'); U = [r for r in NEW if r['part'] == 'u']; C = [r for r in NEW if r['part'] == 'c']
OLDH = [r for r in rd('out/headline2/*.jsonl') if r['seed'] <= 5]; OLDG = [r for r in rd('out/gap1/*.jsonl') if r['part'] == 'u'] + [r for r in rd('out/curve1/*.jsonl') if r['seed'] <= 5]
OWN = rd('out/own2/*.jsonl'); I2 = [r for r in rd('out/intent2/*.jsonl') if r['part'] == 'c']; G1C = [r for r in rd('out/gap1/*.jsonl') if r['part'] == 'c']
M, OPS = ('houston', 'dfw'), ('wing', 'zipline', 'amazon')
def ux(m, a, tag='REAL', seeds=5): return [r for r in U if r['metro'] == m and r['arm'] == a and r['tag'] == tag and r['seed'] <= seeds]
def bw(m, a, tag='REAL', seeds=5, nm='h30v10'): return sum(r['cross'][nm] for r in ux(m, a, tag, seeds))
def wi(m, a, tag='REAL', seeds=5, nm='h30v10'): return sum(r['own'][nm][op][b] for r in ux(m, a, tag, seeds) for op in OPS for b in ('lt200', 'far'))
cut = lambda x, y: 1 - x / y if y else float('nan')
def held(rows, op='all'):
    n = sum(r['cost'][op]['n'] for r in rows if op in r['cost']); return sum(r['cost'][op]['delayed'] + r['cost'][op]['cancelled'] for r in rows if op in r['cost']) / n if n else float('nan')
cc = lambda m, h, v: [r for r in C if r['metro'] == m and r['heights'] == h and r['vol'] == v]
oldc = lambda m, h, v: [r for r in (I2 if v in ('N1', 'N2') and h != 'G1' else G1C) if r['metro'] == m and r['heights'] == h and r['vol'] == ({'N2': 'V14'}.get(v, v) if h == 'G1' else v) and r['seed'] <= 5]
old_bw = lambda m, a: sum(r['cross']['h30v10'] for r in OWN if r['metro'] == m and r['arm'] == a)
def oldcut(m, a, b):
    x = [r for r in OLDH if r['metro'] == m]; return cut(sum(r['v10'] for r in x if r['arm'] == a), sum(r['v10'] for r in x if r['arm'] == b))
def oldG1(m):
    x = [r for r in OLDG if r['metro'] == m]; return cut(sum(r['counts']['h30v10'] for r in x if r['arm'] == 'G1'), sum(r['counts']['h30v10'] for r in x if r['arm'] == 'S1'))
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
pc = lambda x: f'{100 * x:.0f} %'
chk('P1', all(cut(bw(m, 'A2'), bw(m, 'S1')) >= 0.5 for m in M), '; '.join(f'{m} REAL {pc(cut(bw(m, "A2"), bw(m, "S1")))} (old {pc(oldcut(m, "A2", "S1"))})' for m in M))
chk('P2', all(cut(bw(m, 'G1'), bw(m, 'S1')) >= 0.7 for m in M), '; '.join(f'{m} REAL {pc(cut(bw(m, "G1"), bw(m, "S1")))} (old {pc(oldG1(m))})' for m in M))
chk('P3', all(held(cc(m, 'A2', 'N2')) < 0.7 * held(cc(m, 'A0', 'N2')) for m in M), '; '.join(f'{m} A2 {100 * held(cc(m, "A2", "N2")):.1f} % vs A0 {100 * held(cc(m, "A0", "N2")):.1f} %' for m in M))
chk('P4', all(held(cc(m, 'G1', 'V135')) < 0.10 for m in M), '; '.join(f'{m} G1 +-13.5 m {100 * held(cc(m, "G1", "V135")):.1f} % (old {100 * held(oldc(m, "G1", "V135")):.1f} %)' for m in M))
chk('P5', all(bw(m, 'A2') >= 2 * old_bw(m, 'A2') for m in M), '; '.join(f'{m} A2 between REAL {bw(m, "A2")} vs old {old_bw(m, "A2")} ({bw(m, "A2") / old_bw(m, "A2"):.2f}x)' for m in M))
def loo(m, f): return abs(bw(m, 'A2', 'NO_' + f, 3) - bw(m, 'A2', 'REAL', 3))
FACT = ['prof', 'zdfw', 'pop', 'air', 'peak', 'amz15']
chk('P6', all(loo(m, 'peak') > max(loo(m, f) for f in FACT if f != 'peak' and ux(m, 'A2', 'NO_' + f, 3)) for m in M), '; '.join(f'{m} ' + ', '.join(f'{f} {bw(m, "A2", "NO_" + f, 3) - bw(m, "A2", "REAL", 3):+d}' for f in FACT if ux(m, 'A2', 'NO_' + f, 3)) + f' (REAL {bw(m, "A2", "REAL", 3)})' for m in M))
chk('P7', all(wi(m, 'A2') >= 20 * bw(m, 'A2') for m in M), '; '.join(f'{m} A2 within {wi(m, "A2")} vs between {bw(m, "A2")} ({wi(m, "A2") / bw(m, "A2"):.0f}x)' for m in M))
npass = sum(1 for _, ok, _ in P if ok)
L = ['# PHYS1 results table (generated by planned/phys1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Rows: {len(NEW)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Uncoordinated meetings, REAL (seeds 1-5, 30 m / 10 m; within = more than 50 m from own site)', '', '| Metro | Heights | Flights | Between companies | Cut vs S1 | Wing-Wing | Zipline-Zipline | Amazon-Amazon | Within total | 20 m / 5 m between |', '|---|---|---|---|---|---|---|---|---|---|']
for m in M:
    for a in ('A0', 'S1', 'A2', 'G1'):
        x = ux(m, a); w = lambda op: sum(r['own']['h30v10'][op][b] for r in x for b in ('lt200', 'far'))
        L.append(f'| {m} | {a} | {sum(r["flights"] for r in x)} | {bw(m, a)} | {pc(cut(bw(m, a), bw(m, "S1")))} | {w("wing")} | {w("zipline")} | {w("amazon")} | {wi(m, a)} | {bw(m, a, nm="h20v5")} |')
L += ['', '## Leave one out (seeds 1-3, between companies, 30 m / 10 m)', '', '| Metro | Run | S1 | A2 | Cut |', '|---|---|---|---|---|']
for m in M:
    for tag in ['REAL'] + ['NO_' + f for f in FACT]:
        if not ux(m, 'A2', tag, 3): continue
        L.append(f'| {m} | {tag} | {bw(m, "S1", tag, 3)} | {bw(m, "A2", tag, 3)} | {pc(cut(bw(m, "A2", tag, 3), bw(m, "S1", tag, 3)))} |')
L += ['', '## Plan sharing: share of flights held (seeds 1-5; old engine in brackets)', '', '| Metro | Heights / plan | All | Wing | Zipline | Amazon |', '|---|---|---|---|---|---|']
for m in M:
    for h, v in (('A0', 'N2'), ('A2', 'N2'), ('G1', 'V135'), ('G1', 'N2')):
        L.append(f'| {m} | {h} / {v} | ' + ' | '.join(f'{100 * held(cc(m, h, v), op):.1f} % ({100 * held(oldc(m, h, v), op):.1f} %)' for op in ('all',) + OPS) + ' |')
L += ['', '## Flights and routing (REAL, A2, seeds 1-5)', '']
for m in M:
    x = ux(m, 'A2'); s = {k: sum(r['stats'][k] for r in x) for k in x[0]['stats']}
    L.append(f'- {m}: flights {s["n"]}; detoured around airports {s["detour"]} ({100 * s["detour"] / s["n"]:.1f} %); customers redrawn {s["redrawAir"]}; straight through after 20 redraws {s["gaveUpAir"]} ({100 * s["gaveUpAir"] / s["n"]:.1f} %)')
open('planned/phys1_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
